const THEME = {"乾":"势在自强开创，盛极尤不可亢进","姤":"突遇不可轻忽，亦勿一时全投","遁":"退避是保存主动","否":"上下不交，先存实力待松动","观":"先看清全局与人心再介入","剥":"基础受损，宜止损固本","晋":"局面向前显明，宜顺势进阶","大有":"资源已聚，贵在善用勿自满","坤":"以承载顺势成事，先安其位再有所往","复":"转机萌生，宜循原路归正","临":"机会靠近，宜亲临亦防盛不久","泰":"上下相通，宜把握交流之机","大壮":"力强须守正有节","夬":"须决断，宜公开审慎勿躁","需":"条件未齐，等待是蓄势","比":"成事在亲近可信之人","震":"变来突然，先定神再应变","豫":"人心已动，乐观前仍要准备","解":"紧张松动，宜及时处理余患","恒":"贵在持续守常","升":"积小而高，循序上升","井":"资源在，关键是修好取用路径","大过":"承担过重，须调结构","随":"顺势可通，所随之人势须选对","巽":"以柔入事，反复沟通入核心","小畜":"力量积蓄中，宜小步收拢","家人":"先正内部次序","益":"增益之机，利行且使所得归要处","无妄":"守真守常，勿以侥幸求成","噬嗑":"中间有碍，须先咬开障碍","颐":"成败在养根本，慎言慎求","蛊":"旧弊不除新事难成，重在整顿","坎":"险阻相重，宜辨路勿再入险","节":"有节制才能久，规则宜适度","屯":"开端多阻，先立根基，不可急求结果","既济":"看似已成，后段防松懈","革":"旧局难持，变宜顺时取信","丰":"声势足，盛时办事防转衰","明夷":"光明受伤，宜藏锋守正","师":"众事须有主次纪律","离":"事须有所依附，明处更要守内明","旅":"身在不定之局，守分寸","鼎":"更新定型，重在用人与结构","未济":"近结果，最后一步最易失","蒙":"信息尚昧，宜先求明求教","涣":"束缚散开，宜重新聚心","讼":"意见相争，宜止争求理","同人":"求同存异，转机来自公开合作","艮":"该止则止，停错误惯性","贲":"文饰可润事，根本重于表面","大畜":"力足仍须蓄养，待时而发","损":"有所减以保本，舍次守要","睽":"方向暂不一，小事可调大事勿强合","履":"前路可行，步步守礼知险","中孚":"核心在真实可信，内外相应","渐":"事只能渐进，次序重于速度","兑":"沟通能开局，言须真诚有度","困":"外困先守心志，少无效消耗","萃":"人与资源聚，关键在共同中心","咸":"感应是起点，真变在相互触动","蹇":"前路有难，宜反身求助","谦":"守谦反而更易得承接","小过":"可修小处，大事勿越级","归妹":"关系未正位，急定易留后患"}
const YAO_YI = {"乾":["潜藏勿用，养晦待机","德显于野，利见贵人","终日勤奋，夕惕免咎","或跃或潜，审时无咎","飞龙在天，得位得势","亢极有悔，宜知止"],"姤":["系于金柅贞吉有攸往见凶","包有鱼无咎不利宾","臀无肤其行次且厉无大咎","包无鱼起凶","以杞包瓜含章有陨自天","姤其角吝无咎"],"遁":["遁尾厉勿用有攸往","执之用黄牛之革","系遁有疾厉畜臣妾吉","好遁君子吉小人否","嘉遁贞吉","肥遁无不利"],"否":["拔茅茹，贞吉亨","包承小人吉，大人否亨","包羞","有命无咎，畴离祉","休否大人吉","倾否，先否后喜"],"观":["童观小人无咎，君子吝","窥观利女贞","观我生进退","观国之光利用宾于王","观我生君子无咎","观其生君子无咎"],"剥":["剥床以足蔑贞凶","剥床以辨蔑贞凶","剥之无咎","剥床以肤凶","贯鱼以宫人宠无不利","硕果不食君子得舆"],"晋":["晋如摧如贞吉罔孚裕无咎","晋如愁如贞吉受兹介福","众允悔亡","晋如鼫鼠贞厉","悔亡失得勿恤往吉无不利","晋其角维用伐邑"],"大有":["无交害，匪咎","大车以载，有攸往","公用亨于天子","匪其彭，无咎","厥孚交如，威如吉","自天祐之，吉无不利"],"坤":["阴始凝，履霜知坚冰","直方大，内直外方","含章不显，从王无成有终","慎密如括囊","居中守谦，黄裳元吉","阴极战野，宜防极端"],"复":["不远复无祇悔元吉","休复吉","频复厉无咎","中行独复","敦复无悔","迷复凶有灾眚"],"临":["咸临贞吉","咸临吉无不利","甘临无攸利，既忧之无咎","至临无咎","知临大君之宜","敦临吉无咎"],"泰":["拔茅茹，征吉","包荒用冯河，不遐遗","无平不陂，无往不复","翩翩不富，以其邻","帝乙归妹，以祉元吉","城复于隍，勿用师"],"大壮":["壮于趾征凶有孚","贞吉","小人用壮君子用罔贞厉","贞吉悔亡藩决不羸","丧羊于易无悔","羝羊触藩不能退不能遂"],"夬":["壮于前趾往不胜为咎","惕号莫夜有戎勿恤","壮于頄有凶君子夬夬独行遇雨","臀无肤其行次且牵羊悔亡","苋陆夬夬中行无咎","无号终有凶"],"需":["需于郊外，恒心无咎","需于沙，小言终吉","需于泥，防招寇","需于血穴，宜出险","需于酒食，得时则吉","入穴敬客，终吉"],"比":["有孚比之，无咎","比之自内，贞吉","比之匪人","外比之，贞吉","显比，王用三驱","比之无首，凶"],"震":["震来虩虩后笑言哑哑吉","震来厉亿丧贝跻于九陵","震苏苏震行无眚","震遂泥","震往来厉亿无丧有事","震索索视矍矍征凶震不于其躬于其邻无咎"],"豫":["鸣豫凶","介于石，不终日","盱豫悔迟有悔","由豫大有得","贞疾恒不死","冥豫成有渝无咎"],"解":["无咎","田获三狐得黄矢贞吉","负且乘致寇至贞吝","解而拇朋至斯孚","君子维有解吉有孚于小人","公用射隼于高墉之上"],"恒":["浚恒贞凶无攸利","悔亡","不恒其德或承之羞","田无禽","恒其德贞妇人吉夫子凶","振恒凶"],"升":["允升大吉","孚乃利用禴无咎","升虚邑","王用亨于岐山吉无咎","贞吉升阶","冥升利于不息之贞"],"井":["井泥不食旧井无禽","井谷射鲋瓮敝漏","井渫不食为我心恻","井甃无咎","井冽寒泉食","井收勿幕有孚元吉"],"大过":["藉用白茅无咎","枯杨生稊老夫得其女妻","栋桡凶","栋隆吉有它吝","枯杨生华老妇得其士夫","过涉灭顶凶无咎"],"随":["官有渝，贞吉","系小子失丈夫","系丈夫失小子","随有获，贞凶有孚","孚于嘉吉","拘系之乃从维之"],"巽":["进退利武人之贞","巽在床下用史巫纷若吉无咎","频巽吝","悔亡田获三品","贞吉悔亡无不利无初有终","巽在床下丧其资斧贞凶"],"小畜":["复自道，何其咎","牵复吉","舆说辐，夫妻反目","有孚血去惕出","有孚挛如，富以其邻","既雨既处，尚德载"],"家人":["闲有家悔亡","无攸遂在中馈贞吉","家人嗃嗃悔厉吉妇子嘻嘻终吝","富家大吉","王假有家勿恤吉","有孚威如终吉"],"益":["利用为大作元吉无咎","或益之十朋之龟弗克违永贞吉","益之用凶事无咎有孚中行","中行告公从利用为依迁国","有孚惠心勿问元吉","莫益之或击之立心勿恒凶"],"无妄":["无妄往吉","不耕获不菑畬则利","无妄之灾或系之牛","可贞无咎","无妄之疾勿药有喜","无妄行有眚无攸利"],"噬嗑":["屦校灭趾无咎","噬肤灭鼻无咎","噬腊肉遇毒小吝无咎","噬干胏得金矢利艰贞","噬干肉得黄金贞厉无咎","何校灭耳凶"],"颐":["舍尔灵龟观我朵颐凶","颠颐拂经于丘颐征凶","拂颐贞凶十年勿用","颠颐吉虎视眈眈","拂经居贞吉不可涉大川","由颐厉吉利涉大川"],"蛊":["干父之蛊，有子考无咎","干母之蛊，不可贞","干父之蛊，小有悔无大咎","裕父之蛊，往见吝","干父用誉","不事王侯，高尚其事"],"坎":["习坎入于坎窞凶","坎有险求小得","来之坎坎险且枕","樽酒簋贰用缶","坎不盈祗既平无咎","系用徽纆寘于丛棘"],"节":["不出户庭无咎","不出门庭凶","不节若则嗟若无咎","安节亨","甘节吉往有尚","苦节贞凶悔亡"],"屯":["始难磐桓，利建侯居贞","进退两难，婚媾未可急","无虞而往，不如舍","往求婚媾则吉","屯膏不施，小吉大凶","穷极泣血，宜止"],"既济":["曳其轮濡其尾无咎","妇丧其茀勿逐七日得","高宗伐鬼方三年克之小人勿用","繻有衣袽终日戒","东邻杀牛不如西邻之禴祭实受其福","濡其首厉"],"革":["巩用黄牛之革","己日乃革之征吉无咎","征凶贞厉革言三就有孚","悔亡有孚改命吉","大人虎变未占有孚","君子豹变小人革面征凶居贞吉"],"丰":["遇其配主虽旬无咎往有尚","丰其蔀日中见斗往得疑疾有孚发若吉","丰其沛日中见沫折其右肱无咎","丰其蔀日中见斗遇其夷主吉","来章有庆誉吉","丰其屋蔀其家窥其户阒其无人三岁不觌凶"],"明夷":["明夷于飞垂其翼君子于行","明夷夷于左股用拯马壮","明夷于南狩得其大首","入于左腹获明夷之心","箕子之明夷利贞","不明晦初登于天后入于地"],"师":["出师以律，否臧凶","在师中吉，王三锡命","师或舆尸，凶","师左次，无咎","田有禽利执言，长子帅师","大君有命，开国承家小人勿用"],"离":["履错然敬之无咎","黄离元吉","日昃之离不鼓缶而歌","突如其来如焚如死如弃如","出涕沱若戚嗟若吉","王用出征有嘉折首"],"旅":["旅琐琐斯其所取灾","旅即次怀其资得童仆贞","旅焚其次丧其童仆贞厉","旅于处得其资斧我心不快","射雉一矢亡终以誉命","鸟焚其巢旅人先笑后号咷丧牛于易凶"],"鼎":["鼎颠趾利出否得妾以其子无咎","鼎有实我仇有疾不我能即吉","鼎耳革其行塞雉膏不食","鼎折足覆公餗其形渥凶","鼎黄耳金铉利贞","鼎玉铉大吉无不利"],"未济":["濡其尾吝","曳其轮贞吉","未济征凶利涉大川","贞吉悔亡震用伐鬼方三年有赏于大国","贞吉无悔君子之光有孚吉","有孚于饮酒无咎濡其首有孚失是"],"蒙":["发蒙用刑，过则吝","包蒙纳妇，能任家事","见金夫失身，勿取","困于蒙昧，宜求师","居中为童蒙，吉","击蒙可御寇，勿为寇"],"涣":["用拯马壮吉","涣奔其机悔亡","涣其躬无悔","涣其群元吉涣有丘匪夷所思","涣汗其大号涣王居无咎","涣其血去逖出无咎"],"讼":["事勿久缠，小言终吉","不克讼宜退，免灾","食旧德，从王无成","不克讼则复命，安贞","中正决讼，元吉","纵胜亦将三夺，戒争"],"同人":["同人于门，无咎","同人于宗，吝","伏戎于莽，升其高陵","乘其墉，弗克攻吉","同人先号咷后笑","同人于郊，无悔"],"艮":["艮其趾无咎利永贞","艮其腓不拯其随其心不快","艮其限列其夤厉薰心","艮其身无咎","艮其辅言有序悔亡","敦艮吉"],"贲":["贲其趾舍车而徒","贲其须","贲如濡如永贞吉","贲如皤如白马翰如","贲于丘园束帛戋戋","白贲无咎"],"大畜":["有厉利已","舆说輹","良马逐利艰贞","童牛之牿元吉","豮豕之牙吉","何天之衢亨"],"损":["已事遄往无咎酌损之","利贞征凶弗损益之","三人行则损一人","损其疾使遄有喜","或益之十朋之龟弗克违元吉","弗损益之无咎贞吉利有攸往"],"睽":["悔亡丧马勿逐自复","遇主于巷无咎","见舆曳其牛掣其人天且劓","睽孤遇元夫交孚厉无咎","悔亡厥宗噬肤往何咎","睽孤见豕负涂载鬼一车"],"履":["素履往，无咎","履道坦坦，幽人贞吉","眇能视，跛能履，武人为主","履虎尾愬愬，终吉","夬履贞厉","视履考祥，其旋元吉"],"中孚":["虞吉有它不燕","鸣鹤在阴其子和之","得敌或鼓或罢或泣或歌","月几望马匹亡无咎","有孚挛如无咎","翰音登于天贞凶"],"渐":["鸿渐于干小子厉有言无咎","鸿渐于磐饮食衎衎吉","鸿渐于陆夫征不复妇孕不育凶","鸿渐于木或得其桷无咎","鸿渐于陵妇三岁不孕终莫之胜吉","鸿渐于陆其羽可用为仪吉"],"兑":["和兑吉","孚兑吉悔亡","来兑凶","商兑未宁介疾有喜","孚于剥有厉","引兑"],"困":["臀困于株木入于幽谷","困于酒食朱绂方来","困于石据于蒺藜","来徐徐困于金车吝有终","劓刖困于赤绂乃徐有说","困于葛藟于臲卼曰动悔有悔征吉"],"萃":["有孚不终乃乱乃萃","引吉无咎孚乃利用禴","萃如嗟如无攸利往无咎小吝","大吉无咎","萃有位无咎匪孚元永贞悔亡","赍咨涕洟无咎"],"咸":["咸其拇","咸其腓凶居吉","咸其股执其随往吝","贞吉悔亡憧憧往来","咸其脢无悔","咸其辅颊舌"],"蹇":["往蹇来誉","王臣蹇蹇匪躬之故","往蹇来反","往蹇来连","大蹇朋来","往蹇来硕吉利见大人"],"谦":["谦谦君子，用涉大川","鸣谦贞吉","劳谦君子有终","无不利，撝谦","不富以其邻，利用侵伐","鸣谦利用行师征邑国"],"小过":["飞鸟以凶","过其祖遇其妣不及其君遇其臣无咎","弗过防之从或戕之凶","无咎弗过遇之往厉必戒勿用永贞","密云不雨自我西郊公弋取彼在穴","弗遇过之飞鸟离之凶是谓灾眚"],"归妹":["归妹以娣跛能履征吉","眇能视利幽人之贞","归妹以须反归以娣","归妹愆期迟归有时","帝乙归妹其君之袂不如其娣之袂良","女承筐无实士刲羊无血无攸利"]}
const EXTRA = {"乾":{"g":"元始、亨通、利宜、贞正。天德流行，君子法之以自强不息。","y":"纯阳之德，在于健而不息，亦在于知进知退；亢则悔。","z":["宜开创、担当、求名，忌骄傲刚愎","世应看是否得位；动化防亢龙","事业功名象较显，仍须守正"]},"坤":{"g":"利牝马之贞，先迷后得主。地德厚载，君子以厚德载物。","y":"纯阴主顺承、包容、后发；安贞则吉，先动易迷。","z":["宜守成、配合、承载，忌争先强出头","问家宅田土母辈多应","动化防阴极转战"]},"屯":{"g":"始生之难，勿用有攸往，利建侯。云雷郁结，宜立本待时。","y":"万事开头难，宜建侯立基，不可轻进。","z":["创业开局多阻，先立人立规","婚恋宜缓，勿强求速成","用神若动，看能否建侯得助"]},"蒙":{"g":"亨。匪我求童蒙，童蒙求我。初筮告，再三渎则不告。","y":"蒙以养正。启发宜诚，渎问无益。","z":["宜求学、拜师、启蒙，忌自以为是","教育子女看包蒙纳妇之象","再三复问同一事，象多不应"]},"需":{"g":"有孚光亨贞吉，利涉大川。待时而进，非怠惰。","y":"云上于天，饮食宴乐；待其时，乃能济。","z":["条件未齐宜等，勿躁进","有信实准备，大川亦可涉","用神逢合多主暂时胶着"]},"讼":{"g":"有孚窒惕，中吉终凶。利见大人，不利涉大川。","y":"争讼宜止，见中正之人可解；终讼则凶。","z":["官司口舌宜和解，勿穷追","利见贵人、律师、仲裁","不宜扩大投资或远行冒险"]},"师":{"g":"贞，丈人吉，无咎。众行以正，须长者帅之。","y":"地中有水为师，兵众须律，将须正。","z":["团队项目宜有主将与纪律","问军旅竞标竞争看世应强弱","舆尸主多头指挥，凶"]},"比":{"g":"吉。原筮元永贞无咎。不宁方来，后夫凶。","y":"亲附须正，后来不比则凶。","z":["合作为亲比，选人要正","后至无诚者防被弃","世应相生相比为美"]},"小畜":{"g":"亨。密云不雨，自我西郊。积而未降，宜畜德。","y":"风行天上，所积尚小，未可大用。","z":["财名皆在积蓄，勿骤然铺开","密云不雨主未成事实","密云后有密则另当别论"]},"履":{"g":"履虎尾，不咥人，亨。慎行可过险。","y":"柔履刚，礼以行之，危地可亨。","z":["涉险履约宜谨慎守礼","职场上下级相处看履象","武人为主防刚愎"]},"泰":{"g":"小往大来，吉亨。天地交而万物通。","y":"内健外顺，君子道长，宜交通。","z":["合作沟通顺畅之象","宜推进、结盟、求成","无平不陂，盛时防转否"]},"否":{"g":"不利君子贞，大往小来。天地不交。","y":"内阴外阳，闭塞；俭德避难。","z":["不宜强推合作扩张","宜收敛保存实力","倾否则有先否后喜之机"]},"同人":{"g":"同人于野，亨。利涉大川，利君子贞。","y":"火天同人，文明以健，公心则同。","z":["宜公开合作、寻同志","同人于宗则吝，格局宜大","先号后笑，先难后合"]},"大有":{"g":"元亨。火在天上，所有盛大。","y":"柔得尊位大中，上下应之。","z":["财资源丰，贵在不自满","公用亨于天子，利见上","自天祐之，守正乃吉"]},"谦":{"g":"亨，君子有终。山在地中，卑而不可逾。","y":"亏盈益谦，天道人道皆然。","z":["宜退让、低调成事","劳谦有终，功成不居","侵伐亦以谦道，师出有名"]},"豫":{"g":"利建侯行师。雷出地奋，豫乐可动。","y":"顺以动，故豫；豫而怠则凶。","z":["宜发动、建侯、鼓舞士气","鸣豫逸乐则凶","介于石，见几宜速"]},"随":{"g":"元亨利贞，无咎。泽中有雷，随时而动。","y":"刚来而下柔，动而说，随。","z":["宜随缘、随贵人、随大势","所随不正则失","有获而贞凶，防利令智昏"]},"蛊":{"g":"元亨，利涉大川。先甲三日，后甲三日。","y":"山下有风，败坏已久，治蛊宜有始有终。","z":["宜整顿、改革、清理旧弊","干父干母之蛊，家族企业事","裕蛊则吝，不可拖延"]},"临":{"g":"元亨利贞。至于八月有凶。刚浸而长。","y":"地泽临，以上临下，亲临督导。","z":["宜亲临现场、管理、督导","盛势不久，防八月有凶之戒","甘临无实，宜忧之"]},"观":{"g":"盥而不荐，有孚颙若。风行地上，省方观民。","y":"大观在上，中正以观天下。","z":["宜考察、调研、参观学习","童观则浅，窥观限女贞","观国之光，利见大场景"]},"噬嗑":{"g":"亨。利用狱。颐中有物，啮而后合。","y":"明罚敕法，除间隔而后通。","z":["宜处理梗阻、纠纷、法律事","用狱象显，证据要硬","灭趾灭耳看刑责轻重"]},"贲":{"g":"亨。小利有攸往。文明以止，人文也。","y":"山下有火，文饰；白贲则无咎。","z":["宜包装、设计、礼仪、表面功夫","文胜质则吝，根本仍要实","丘园束帛，俭约亦吉"]},"剥":{"g":"不利有攸往。山附于地，剥。","y":"柔变刚，消息盈虚；硕果不食尚存。","z":["宜止损收缩，勿扩张","床足被剥，基础动摇","硕果不食，留火种待复"]},"复":{"g":"亨。出入无疾，朋来无咎。反复其道，七日来复。","y":"雷在地中，一阳来复，生意又萌。","z":["转机初现，宜回复正道","七日来复，应期可参","迷复则凶，勿再失方向"]},"无妄":{"g":"元亨利贞。其匪正有眚，不利有攸往。","y":"天下雷行，物与无妄；动以天，勿妄。","z":["宜本分正道，忌妄求","无妄之灾须防飞来横祸","不耕而获不可存侥幸"]},"大畜":{"g":"利贞。不家食吉，利涉大川。刚上而尚贤。","y":"天在山中，以大畜小，畜德畜贤。","z":["宜蓄学、蓄财、蓄势","不家食，利外出就养","童牛牿、豮牙，防患于未然"]},"颐":{"g":"贞吉。观颐，自求口实。山下有雷，养。","y":"慎言语、节饮食，养正则吉。","z":["问养生、饮食、口才、供养","朵颐贪食则凶","由颐利涉，得养则济"]},"大过":{"g":"栋桡，利有攸往，亨。泽灭木，本末弱。","y":"大者过也；独立不惧，遁世无闷。","z":["负担过重，须改结构","栋桡主栋梁不支","过涉灭顶，勿再冒险逞强"]},"坎":{"g":"有孚维心亨，行有尚。习坎，重险。","y":"水流而不盈，行险而不失其信。","z":["险中求通，心亨乃济","连续困难，勿再入新险","求小得可，勿贪大"]},"离":{"g":"利贞，亨。畜牝牛，吉。明两作。","y":"重明以丽乎正，乃化成天下。","z":["宜文书、文明、附丽贵人","突如其来防灾焚","出征折首，名实要符"]},"咸":{"g":"亨，利贞，取女吉。山泽通气，二气感应。","y":"柔上而刚下，止而说，男下女。","z":["婚恋感应之卦，重互动","憧憧往来，朋从尔思","咸其辅颊舌，戒空言"]},"恒":{"g":"亨，无咎，利贞，利有攸往。雷风相与，恒。","y":"久于其道，天地万物之情可见。","z":["宜长期关系、契约、守常","不恒其德则羞","振恒则凶，勿躁动无常"]},"遁":{"g":"亨，小利贞。天下有山，遁。","y":"刚当位而应，与时行也；退以成亨。","z":["宜退守、回避、抽身","好遁嘉遁为美，肥遁无不利","系遁有疾，藕断丝连则厉"]},"大壮":{"g":"利贞。雷在天上，壮。","y":"刚以动，故壮；非礼弗履。","z":["力量强盛，忌用壮逞强","羝羊触藩，进退两难之戒","藩决不羸，则可进"]},"晋":{"g":"康侯用锡马蕃庶，昼日三接。明出地上。","y":"顺而丽乎大明，柔进而上行。","z":["宜晋升、表彰、见光","晋如鼫鼠则厉，勿贪位","失得勿恤，往吉"]},"明夷":{"g":"利艰贞。明入地中，明夷。","y":"内文明而外柔顺，以蒙大难。","z":["光明受伤，宜晦藏","艰贞自守，勿露锋","箕子象，守正于难中"]},"家人":{"g":"利女贞。风自火出，家人。","y":"女正位乎内，男正位乎外，家道正。","z":["家事、团队内部治理","闲有家，防患未然","嘻嘻终吝，家教宜严"]},"睽":{"g":"小事吉。上火下泽，睽。","y":"二女同居其志不同行；异中求同。","z":["分歧之象，宜做小事","遇主于巷，意外相合","载鬼一车，疑心生暗鬼"]},"蹇":{"g":"利西南，不利东北；利见大人，贞吉。","y":"山上有水，蹇；见险而能止。","z":["前路难，宜西南求助","往蹇来反，退步反安","大蹇朋来，难中得友"]},"解":{"g":"利西南，无所往其来复吉，有攸往夙吉。","y":"雷雨作，解；百果草木皆甲坼。","z":["困境将解，宜速处理余患","负且乘致寇，名实勿倒","射隼高墉，除害务尽"]},"损":{"g":"有孚，元吉，无咎，可贞，利有攸往。曷之用二簋可用享。","y":"损下益上，其道上行；损而有孚。","z":["宜减损开支欲望，成大事","损疾有喜，去病如损","弗损益之，有时不损反益"]},"益":{"g":"利有攸往，利涉大川。风雷益。","y":"损上益下，民说无疆；迁善改过。","z":["宜进取、投资于人、迁善","中行告公，正大光明","莫益或击，勿贪得无厌"]},"夬":{"g":"扬于王庭，孚号有厉；告自邑，不利即戎，利有攸往。","y":"泽上于天，夬；刚决柔也。","z":["宜决断、公布、除小人","不利即戎，勿用暴力硬闯","无号终有凶，优柔则败"]},"姤":{"g":"女壮，勿用取女。天下有风，姤。","y":"柔遇刚，品物咸章；一阴始生。","z":["突遇机会或人，宜审","女壮勿取，防一阴消阳","包有鱼，宜有节制"]},"萃":{"g":"亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。","y":"泽上于地，萃；聚以正也。","z":["聚会、集资、团队凝聚","王假有庙，宜有共同信念","赍咨涕洟，聚而未安"]},"升":{"g":"元亨，用见大人，勿恤，南征吉。","y":"地中生木，升；柔以时升。","z":["宜循序升迁、积累","允升大吉，得信实之助","冥升不息，暗中仍须正"]},"困":{"g":"亨，贞，大人吉，无咎。有言不信。","y":"泽无水，困；君子以致命遂志。","z":["受困宜守志，言多不信","困于酒食，反或为机","动悔有悔，行乃解"]},"井":{"g":"改邑不改井，无丧无得，往来井井。汔至亦未繘井，羸其瓶，凶。","y":"木上有水，井；劳民劝相。","z":["资源在己，修通取用路径","井泥不食，须淘治","井收勿幕，成功勿独占"]},"革":{"g":"己日乃孚，元亨利贞，悔亡。","y":"泽中有火，革；汤武革命顺天应人。","z":["改革须己日取信","虎变豹变，大人君子各有分","革面小人，未可尽信"]},"鼎":{"g":"元吉，亨。木上有火，鼎。","y":"圣人亨以享上帝，而大亨以养圣贤。","z":["宜换新人、新制度、新格局","鼎折足覆餗，不胜其任则凶","黄耳金铉，得中得助"]},"震":{"g":"亨。震来虩虩，笑言哑哑；震惊百里，不丧匕鬯。","y":"洊雷震，君子以恐惧修省。","z":["突变惊吓后反能定","不丧匕鬯，主不失主心","震遂泥，陷则难振"]},"艮":{"g":"艮其背，不获其身；行其庭，不见其人，无咎。","y":"兼山艮，君子以思不出其位。","z":["宜止、静、守边界","艮其腓其限，止得不当则厉","敦艮吉，止于至善"]},"渐":{"g":"女归吉，利贞。山上有木，渐。","y":"进得位，往有功；止而巽，动不穷。","z":["婚嫁升迁皆宜渐进","鸿渐于干至陆，循序","夫征不复象，防有去无回"]},"归妹":{"g":"征凶，无攸利。泽上有雷，归妹。","y":"征凶位不当；无攸利柔乘刚。","z":["婚约关系不正则凶","愆期迟归，时未至","承筐无实，有名无实"]},"丰":{"g":"亨，王假之，勿忧，宜日中。","y":"雷电皆至，丰；明以动，故丰。","z":["盛时宜把握日中","丰其蔀则暗，防蔽明","窥户无人，盛极转空"]},"旅":{"g":"小亨，旅贞吉。山上有火，旅。","y":"旅琐琐取灾；柔得中乎外而顺乎刚。","z":["出行、寄居、客地发展","即次怀资，安顿为先","焚巢丧牛，失其所安"]},"巽":{"g":"小亨，利有攸往，利见大人。","y":"重巽以申命；柔皆顺乎刚。","z":["宜申命、沟通、渗透","进退利武人，决断要有力","巽在床下，过卑则丧斧"]},"兑":{"g":"亨，利贞。丽泽兑，君子以朋友讲习。","y":"说以利贞，是以顺乎天而应乎人。","z":["宜洽谈、教学、联谊","来兑凶，防佞悦","商兑未宁，商量未定"]},"涣":{"g":"亨。王假有庙，利涉大川，利贞。","y":"风行水上，涣；先王享于帝立庙。","z":["散中求聚，立庙立心","涣其群元吉，解散小集团","涣汗大号，号令宜畅"]},"节":{"g":"亨。苦节不可贞。泽上有水，节。","y":"节以制度，不伤财不害民。","z":["宜节约、立规矩","不出户庭无咎，当止则止","苦节则凶，过严不可久"]},"中孚":{"g":"豚鱼吉，利涉大川，利贞。","y":"柔在内而刚得中，说而巽，孚乃化邦。","z":["诚信感通，可涉大川","鸣鹤在阴，声应气求","翰音登天，虚声无实则凶"]},"小过":{"g":"亨，利贞，可小事不可大事。飞鸟遗之音，不宜上宜下，大吉。","y":"过以利贞，与时行也；小者过而亨。","z":["宜小心事、细节修正","不可大事、不宜向上硬冲","飞鸟以凶，过亢则灾"]},"既济":{"g":"亨小，利贞，初吉终乱。","y":"水在火上，既济；终止则乱，其道穷。","z":["事已成，防终乱","濡尾无咎，慎终","东邻杀牛不如西邻禴祭，诚重于奢"]},"未济":{"g":"亨，小狐汔济，濡其尾，无攸利。","y":"火在水上，未济；辨物居方。","z":["未完成，最后勿大意","小狐濡尾，差一步仍凶","有孚饮酒，成功后勿失度"]},"遯":{"g":"亨，小利贞。天下有山，遁。","y":"刚当位而应，与时行也；退以成亨。","z":["宜退守、回避、抽身","好遁嘉遁为美，肥遁无不利","系遁有疾，藕断丝连则厉"]}}

function weaveSchool(base, extra) {
  const a = String(base || '').trim()
  const b = String(extra || '').trim()
  if (!b) return a
  if (!a) return b
  if (a.indexOf(b) >= 0) return a
  const head = /[。！？；]$/.test(a) ? a : a + '。'
  return head + b
}

function p(text) { return { type: 'p', text } }
function quote(text, from) { return { type: 'quote', text, from: from || '' } }
function list(items) { return { type: 'list', items } }
function note(text) { return { type: 'note', text } }

function buildGuaRecords() {
  const out = []
  for (const pk of PALACE_ORDER) {
    const palace = PALACES[pk]
    palace.gua.forEach((lines, si) => {
      const key = lines.join('')
      const meta = GUA64_NAMES[key]
      const alias = meta.alias
      const ci = getGuaCi(alias) || {}
      const lower = TRIGRAMS[linesToTrigramKey(lines.slice(0, 3))]
      const upper = TRIGRAMS[linesToTrigramKey(lines.slice(3, 6))]
      const theme = THEME[alias] || '审时度势，守正知变'
      const ex = EXTRA[alias] || EXTRA[meta.name] || {}
      const bh = getBaihua(alias) || getBaihua(meta.name) || null
      const mojia = getMojia(alias) || getMojia(meta.name) || null
      const yaoYiRaw = (bh && bh.yao) || YAO_YI[alias] || []
      const yaoYi = yaoYiRaw.map((line, i) => weaveSchool(line, mojia && mojia.yao && mojia.yao[i]))
      const shi = SHI_POS[si]
      // lines: 下→上；yaoView: 上→下（画面从上往下画六爻）
      const yaoView = lines.slice().reverse().map((v) => ({ yang: !!v }))
      out.push({
        alias,
        fullName: meta.name,
        palaceKey: pk,
        palaceName: palace.name,
        palaceWuxing: palace.wuxing,
        stage: STAGE[si],
        stageIndex: si,
        shiPos: shi,
        shiLabel: YAO_POS[shi],
        yingLabel: YAO_POS[(shi + 3) % 6],
        lines: lines.slice(),
        yaoView,
        lowerName: lower.name,
        upperName: upper.name,
        lowerNature: lower.nature,
        upperNature: upper.nature,
        nameWhy: ci.nameWhy || '',
        guaci: ci.guaci || '',
        yaoci: ci.yaoci || [],
        theme,
        // 白话优先用零基础详解
        guaciYi: weaveSchool((bh && bh.g) || ex.g || ('大意：' + theme), mojia && mojia.guaci),
        yili: weaveSchool((bh && bh.y) || ex.y || theme, mojia && mojia.yili),
        zhan: (bh && bh.z) || ex.z || [theme],
        yaoYi,
        mojia
      })
    })
  }
  return out
}

function blocksForGua(g, opts) {
  opts = opts || {}
  const blocks = []
  if (!opts.standalone) {
    blocks.push(p('━━━━━━━━━━━━━━━━'))
    blocks.push(p('【' + g.fullName + ' · ' + g.alias + '】'))
  }
  blocks.push(p('结构：上' + g.upperName + '（' + g.upperNature + '）· 下' + g.lowerName + '（' + g.lowerNature + '）。'))
  blocks.push(p('京房八宫：' + g.palaceName + '宫 · ' + g.stage + '（宫五行' + g.palaceWuxing + '）；世在' + g.shiLabel + '爻，应在' + g.yingLabel + '爻。'))
  blocks.push(p('卦德主旨：' + g.theme + '。'))
  if (g.nameWhy) {
    blocks.push(p('取象释名：' + g.nameWhy))
  }
  if (g.guaci) {
    blocks.push(quote(g.guaci, g.alias + '·卦辞'))
    blocks.push(p('卦辞解释：' + g.guaciYi))
  }
  blocks.push(p('义理提要：' + g.yili))
  const yaoItems = (g.yaoci || []).map((line, i) => {
    const tip = (g.yaoYi && g.yaoYi[i]) ? g.yaoYi[i] : ''
    return tip ? (line + ' ／ ' + tip) : line
  })
  if (yaoItems.length) {
    blocks.push(p('爻辞解释：'))
    blocks.push(list(yaoItems))
  }
  blocks.push(p('占事要点：'))
  blocks.push(list(g.zhan))
  blocks.push(note('断具体人事仍须合用神、动变、日月；本篇为卦德与辞象教材，不作绝对预言。'))
  return blocks
}

