/** 八宫目录树：供卦典总图点击 */
function buildPalaceCatalog() {
  const records = buildGuaRecords()
  return PALACE_ORDER.map((pk) => {
    const meta = PALACE_META[pk]
    const guas = records.filter((g) => g.palaceKey === pk).map((g) => ({
      alias: g.alias,
      fullName: g.fullName,
      stage: g.stage,
      stageIndex: g.stageIndex,
      shiLabel: g.shiLabel,
      theme: g.theme,
      palaceName: g.palaceName,
      palaceWuxing: g.palaceWuxing,
      lines: g.lines,
      yaoView: g.yaoView
    }))
    return {
      key: pk,
      title: meta.title,
      wuxing: meta.wuxing,
      tip: meta.tip,
      symbol: meta.symbol,
      label: meta.title + '·' + meta.wuxing,
      guas
    }
  })
}

