/** 六爻位象（下→上）：共性内涵 */
const YAO_WEI = [
  { key: '初', title: '事之始', body: '根基、起步、百姓之位。看事情刚开头时的状态与态度。' },
  { key: '二', title: '内卦之中', body: '得中、臣僚、内部骨干。看内部是否稳妥、是否有人托底。' },
  { key: '三', title: '人位多凶', body: '内卦尽头，进退关口。多劳、多变，宜谨慎勿躁进。' },
  { key: '四', title: '近君多惧', body: '外卦之初，接近权力与结果。进退两难时宜审时度势。' },
  { key: '五', title: '君位得中', body: '尊位、决策核心。得中则主事，看主导力量是否正当。' },
  { key: '上', title: '事之终', body: '收尾、极端、退场。过刚则亢，过柔则穷，宜知止。' }
]

function trigramXiangCard(name, nature, roleLabel) {
  const meta = TRIGRAM_XIANG[name] || { de: '', family: '', plain: '', xiang: '' }
  return {
    role: roleLabel,
    name: name || '',
    nature: nature || '',
    symbol: (Object.values(TRIGRAMS).find((t) => t.name === name) || {}).symbol || '',
    wuxing: (Object.values(TRIGRAMS).find((t) => t.name === name) || {}).wuxing || '',
    de: meta.de,
    family: meta.family,
    plain: meta.plain,
    xiang: meta.xiang,
    head: roleLabel + ' · ' + (name || '') + (nature ? '（' + nature + '）' : '')
  }
}

/**
 * 卦象解释（精简）：成卦一句话 + 上下经卦一行 + 读法一句
 */
function buildXiangExplain(g) {
  const upper = trigramXiangCard(g.upperName, g.upperNature, '上')
  const lower = trigramXiangCard(g.lowerName, g.lowerNature, '下')
  const pure = g.upperName === g.lowerName
  const nameWhy = g.nameWhy || ''

  // 上☰乾天·健（父） · 下☷坤地·顺（母）
  const structure = '上' + (upper.symbol || '') + upper.name + (upper.nature || '')
    + '·' + (upper.de || '') + (upper.family ? '（' + upper.family + '）' : '')
    + '  ·  下' + (lower.symbol || '') + lower.name + (lower.nature || '')
    + '·' + (lower.de || '') + (lower.family ? '（' + lower.family + '）' : '')

  // 读法一句，不重复 nameWhy
  let readTip = ''
  if (pure) {
    readTip = '纯卦，性情专一：' + (upper.plain || (upper.de + '。'))
  } else {
    readTip = '内（下）看自己——' + (lower.de || '') + '；外（上）看环境或对方——' + (upper.de || '') + '。'
  }
  const shiHint = (g.shiLabel && g.yingLabel)
    ? '世在' + g.shiLabel + '、应在' + g.yingLabel + '。'
    : ''
  if (g.mojia && g.mojia.xiang) {
    readTip = weaveSchool(readTip, g.mojia.xiang)
  }

  return {
    nameWhy,
    structure,
    readTip: (readTip + shiHint).trim(),
    // 兼容旧字段（预览若残留）
    plain: nameWhy || readTip,
    upper,
    lower,
    yaoRoles: []
  }
}

/**
 * 单卦详情：供卦象板（大图+爻辞对齐）与白话区使用
 * yaoBoard 自上而下：上爻 → 初爻
 */
function getGuaXiangjie(alias) {
  if (!alias) return null
  const g = buildGuaRecords().find((item) => item.alias === alias || item.fullName === alias)
  if (!g) return null

  const posNamesTopDown = ['上', '五', '四', '三', '二', '初']
  const yaoBoard = []
  for (let top = 0; top < 6; top += 1) {
    const lineIndex = 5 - top // 0=初 … 5=上
    const yang = !!(g.lines && g.lines[lineIndex])
    const classic = (g.yaoci && g.yaoci[lineIndex]) || ''
    // 从「初九：xxx」抽出正文；位名用六/九
    let classicBody = classic
    const m = classic.match(/^[^：:]+[：:]\s*(.*)$/)
    if (m) classicBody = m[1]
    const bit = yang ? '九' : '六'
    const pos = posNamesTopDown[top]
    // 传统称谓：初九/上六；中间为九二、六三、九四、九五
    const posLabel = (pos === '初' || pos === '上') ? (pos + bit) : (bit + pos)
    yaoBoard.push({
      lineIndex,
      yang,
      posLabel,
      classic: classicBody || classic,
      classicFull: classic,
      tip: (g.yaoYi && g.yaoYi[lineIndex]) || '',
      isShi: g.shiPos === lineIndex,
      isYing: ((g.shiPos + 3) % 6) === lineIndex
    })
  }

  const structureText = '上' + g.upperName + g.upperNature + ' · 下' + g.lowerName + g.lowerNature
    + ' · ' + g.palaceName + '宫' + g.stage
    + '（' + g.palaceWuxing + '）世' + g.shiLabel + ' 应' + g.yingLabel

  const xiangExplain = buildXiangExplain(g)

  return Object.assign({}, g, {
    title: g.fullName,
    summary: g.palaceName + '宫' + g.stage + ' · ' + g.theme,
    categoryLabel: '卦典 · ' + g.palaceName + '宫',
    structureText,
    yaoBoard,
    xiangExplain,
    // 白话区
    plainGuaci: g.guaciYi,
    plainYili: g.yili,
    plainZhan: g.zhan || [],
    // 爻辞解释：原文+白话+圣言连写，一行通顺、不拆块
    plainYao: yaoBoard.map((row) => {
      const classic = row.classic || row.classicFull || ''
      const xx = getXiaoxiang(g.alias, row.lineIndex)
      let tip = cleanYaoExplain(row.tip, row.posLabel, classic)
      tip = enrichYaoTip(tip, xx)
      const sage = buildYaoSageLine(g.alias, row.lineIndex, classic, tip)
      const flow = joinYaoExplainFlow(classic, tip, sage)
      return {
        posLabel: row.posLabel,
        classic: flow.classic,
        rest: flow.rest,
        tip,
        sage,
        text: flow.text
      }
    }),
    blocks: blocksForGua(g, { standalone: true })
  })
}

/** 正则转义（勿用 replace 的 '$&' 写法，嵌入 HTML 打包时会被当成特殊替换符） */
function escapeRegExp(s) {
  return String(s || '').replace(/[.*+?^${}()|[\]\\]/g, (ch) => '\\' + ch)
}

/** 句末补句号，便于连写 */
function ensureSentenceEnd(s) {
  let t = String(s || '').trim()
  if (!t) return ''
  if (!/[。．！？；…」』）)]$/.test(t)) t += '。'
  return t
}

/**
 * 拆成「原文 / 后文」便于原文加粗、白话不粗，仍连写不断行
 * 返回 { classic, rest, text }
 */
function joinYaoExplainFlow(classic, tip, sage) {
  const c = ensureSentenceEnd(classic)
  let t = String(tip || '').trim()
  let s = String(sage || '').trim()
  const restParts = []

  if (t) {
    if (c) {
      const cCore = c.replace(/[。．！？；…]+$/, '')
      const norm = (str) => String(str || '').replace(/[，,。．！？；：:\s「」『』]/g, '')
      // 白话与原文实质相同则跳过，避免「富家，大吉。富家大吉。」
      if (norm(t) && norm(t) === norm(cCore)) {
        t = ''
      } else if (t === cCore || t.indexOf(cCore) === 0) {
        t = t.slice(cCore.length).replace(/^[：:，,\s]+/, '')
      }
    }
    t = ensureSentenceEnd(t)
    if (t) restParts.push(t)
  }

  if (s) {
    s = s.replace(/^[。．\s]+/, '')
    if (s) restParts.push(s)
  }

  const rest = restParts.join('').replace(/。{2,}/g, '。').replace(/——。/g, '——').trim()
  const text = (c + rest).replace(/。{2,}/g, '。').trim()
  return { classic: c, rest, text }
}

/**
 * 爻辞解释区的白话：直接说意思，不重复位名、不贴套话。
 */
function cleanYaoExplain(tip, posLabel, classicBody) {
  let t = String(tip || '').trim()
  if (!t) return ''

  // 1) 先剥「四爻（接近结果）：」——须先于位名
  t = t.replace(/^[初上]爻（[^）]*）[：:]\s*/, '')
  t = t.replace(/^[二三四五]爻（[^）]*）[：:]\s*/, '')

  // 2) 剥位名 + 可选摘句：「初九「潜龙勿用」：」「六四：」
  const pos = String(posLabel || '')
  if (pos) {
    const ep = escapeRegExp(pos)
    t = t.replace(new RegExp('^' + ep + '「[^」]*」[：:]\\s*'), '')
    t = t.replace(new RegExp('^' + ep + '『[^』]*』[：:]\\s*'), '')
    t = t.replace(new RegExp('^' + ep + '[：:]\\s*'), '')
  }
  t = t.replace(/^(?:初[九六]|上[九六]|[九六][二三四五])「[^」]*」[：:]\s*/, '')
  t = t.replace(/^(?:初[九六]|上[九六]|[九六][二三四五])[：:]\s*/, '')

  // 3) 去掉「经文大意 / 零基础可记」套话
  t = t.replace(/。?\s*经文大意是「[^」]*」[。.]?/g, '')
  t = t.replace(/。?\s*零基础可记[：:][^。]*[。.]?/g, '')

  // 4) 「辞意复述——白话」：只留破折号后的直接解释
  const dashParts = t.split(/[—－]{1,2}/)
  if (dashParts.length >= 2) {
    const right = dashParts.slice(1).join('—').trim()
    if (right.length >= 2) t = right
  }

  // 5) 若仍以完整原文起头，剥掉
  if (classicBody) {
    const body = String(classicBody).replace(/[。．.]+$/, '').trim()
    if (body) {
      const esc = escapeRegExp(body)
      t = t.replace(new RegExp('^「' + esc + '」[：:]\\s*'), '')
      t = t.replace(new RegExp('^' + esc + '[：:，,\\s]*'), '')
    }
  }
  t = t.replace(/^「[^」]+」[：:]\s*/, '')

  t = t.replace(/。{2,}/g, '。').replace(/^[。\s]+/, '').trim()
  if (t === '。') t = ''
  return t
}

/** @deprecated 兼容旧调用名 */
function stripYaoExplainLead(tip, posLabel, classicBody) {
  return cleanYaoExplain(tip, posLabel, classicBody)
}

